// ─── File: OrderSagaDemo.java ───
// Runnable demo: orchestrated Saga with compensations when payment fails.

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class OrderSagaDemo {

    private static final Logger log = Logger.getLogger("ordersaga");

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        OrderService orders = new OrderService();
        InventoryService inventory = new InventoryService(5);
        PaymentService payment = new PaymentService(new BigDecimal("100000"));
        DeliveryService delivery = new DeliveryService();
        OrderSagaOrchestrator saga = new OrderSagaOrchestrator(orders, inventory, payment, delivery);

        log.info("===== SUCCESS: payment Rs.50,000 succeeds =====");
        saga.placeOrder("SAV2001", "BOOK-1", 2, new BigDecimal("50000"));

        log.info("===== FAILURE: payment Rs.150,000 fails → compensate =====");
        saga.placeOrder("SAV2001", "BOOK-1", 2, new BigDecimal("150000"));
    }
}

// ─── model/Order.java ───
class Order {
    final String orderId; final String accountId; final BigDecimal amount; String status;
    Order(String orderId, String accountId, BigDecimal amount) {
            this.orderId = orderId;
            this.accountId = accountId
            this.amount = amount
            this.status = "CREATED";
    }
}

// ─── model/SagaState.java ───
enum SagaState { STARTED, ORDER_CREATED, STOCK_RESERVED, PAID, DELIVERED, COMPENSATING, COMPLETED, CANCELLED }

// ─── service/OrderService.java ───
class OrderService {
    private static final Logger log = Logger.getLogger("ordersaga");
    private final Map<String, Order> db = new HashMap<>();
    Order create(String accountId, BigDecimal amount) {          // T1
        Order o = new Order("ORD-" + UUID.randomUUID().toString().substring(0, 8), accountId, amount);
        db.put(o.orderId, o);
        log.info(() -> "[ORDER] created " + o.orderId + " (local commit)");
        return o;
    }
    void cancel(String orderId) {                                 // C1 — idempotent
        Order o = db.get(orderId);
        if (o != null && !"CANCELLED".equals(o.status)) {
            o.status = "CANCELLED";
            log.warning(() -> "[ORDER] COMPENSATE cancel " + orderId);
        }
    }
    void complete(String orderId) { db.get(orderId).status = "COMPLETED"; }
}

// ─── service/InventoryService.java ───
class InventoryService {
    private static final Logger log = Logger.getLogger("ordersaga");
    private int available; private int reserved = 0;
    InventoryService(int available) { this.available = available; }
    void reserve(String sku, int qty) {                           // T2
        if (available < qty) throw new IllegalStateException("out of stock");
        available -= qty; reserved += qty;
        log.info(() -> "[INVENTORY] reserved " + qty + " of " + sku + " (available=" + available + ")");
    }
    void release(String sku, int qty) {                           // C2 — idempotent-safe
        available += qty; reserved = Math.max(0, reserved - qty);
        log.warning(() -> "[INVENTORY] COMPENSATE release " + qty + " of " + sku + " (available=" + available + ")");
    }
}

// ─── service/PaymentService.java ───
class PaymentService {
    private static final Logger log = Logger.getLogger("ordersaga");
    private final BigDecimal failAbove;
    PaymentService(BigDecimal failAbove) { this.failAbove = failAbove; }
    void charge(String orderId, BigDecimal amount) {              // T3 (may fail)
        if (amount.compareTo(failAbove) > 0) {
            log.severe(() -> "[PAYMENT] FAILED for " + orderId + " Rs." + amount);
            throw new RuntimeException("payment declined");
        }
        log.info(() -> "[PAYMENT] charged " + orderId + " Rs." + amount);
    }
}

// ─── service/DeliveryService.java ───
class DeliveryService {
    private static final Logger log = Logger.getLogger("ordersaga");
    void schedule(String orderId) {                               // T4 — only after PAID (not compensatable)
        log.info(() -> "[DELIVERY] scheduled for " + orderId);
    }
}

// ─── orchestrator/OrderSagaOrchestrator.java ───
class OrderSagaOrchestrator {
    private static final Logger log = Logger.getLogger("ordersaga");
    private final OrderService orders; private final InventoryService inventory;
    private final PaymentService payment; private final DeliveryService delivery;
    OrderSagaOrchestrator(OrderService o, InventoryService i, PaymentService p, DeliveryService d) {
        orders = o; inventory = i; payment = p; delivery = d;
    }

    void placeOrder(String accountId, String sku, int qty, BigDecimal amount) {
        SagaState state = SagaState.STARTED;
        Order order = null;
        try {
            order = orders.create(accountId, amount);  state = SagaState.ORDER_CREATED;   // T1
            inventory.reserve(sku, qty);                state = SagaState.STOCK_RESERVED;  // T2
            payment.charge(order.orderId, amount);      state = SagaState.PAID;            // T3
            delivery.schedule(order.orderId);           state = SagaState.DELIVERED;       // T4
            orders.complete(order.orderId);             state = SagaState.COMPLETED;
            SagaState fs = state;
            log.info(() -> "[SAGA] " + order.orderId + " → " + fs);
        } catch (RuntimeException e) {
            log.severe(() -> "[SAGA] failure at " + e.getMessage() + " → compensating in reverse");
            // Run compensations for whatever already committed, in REVERSE order.
            if (state.ordinal() >= SagaState.STOCK_RESERVED.ordinal()) inventory.release(sku, qty);  // C2
            if (state.ordinal() >= SagaState.ORDER_CREATED.ordinal() && order != null) orders.cancel(order.orderId); // C1
            log.warning("[SAGA] compensation complete → CANCELLED, no money captured");
        }
    }
}

// ─── BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tH:%1$tM:%1$tS %2$-7s %3$s%n",
                new Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
